
%% MATH 155 - Homework 4, Problem 3
% Statistical Image Denoising
% Norah Lynch
%
% 3x3 Geometric Mean Filter
% 3x3 Alpha-Trimmed Mean Filter (d = 4)
% Optional SNR evaluation with clean reference

clear; clc; close all;

%% Select noisy input image
I = imread('HW4Q3_original_image.jpg');


%% Convert to grayscale
if size(I, 3) == 3
    I = 0.2989*double(I(:,:,1)) + ...
        0.5870*double(I(:,:,2)) + ...
        0.1140*double(I(:,:,3));
end

I = double(I);

% Convert standard 8-bit image to [0,1]
if max(I(:)) > 1
    I = I / 255;
end

[M, N] = size(I);

%% Create replicated boundary padding
rowIdx = [1, 1:M, M];
colIdx = [1, 1:N, N];

Ipad = I(rowIdx, colIdx);

%% Initialize output images
Igeo = zeros(M,N);
Ialpha = zeros(M,N);

%% Alpha-trimmed mean parameter
d = 4;
windowSize = 9;
remaining = windowSize - d;

%% Apply 3x3 filters
for i = 1:M
    for j = 1:N

        window = Ipad(i:i+2, j:j+2);
        values = window(:);

        %% Geometric mean filter
        % Logarithms avoid numerical underflow.
        % True zero pixels give a zero geometric mean.

        if any(values == 0)
            Igeo(i,j) = 0;
        else
            Igeo(i,j) = exp(mean(log(values)));
        end

        %% Alpha-trimmed mean filter
        sortedValues = sort(values);

        % Remove two smallest and two largest
        trimmedValues = ...
            sortedValues(1+d/2:end-d/2);

        Ialpha(i,j) = ...
            sum(trimmedValues) / remaining;

    end
end

%% Clip images to valid range
Igeo = max(0, min(1, Igeo));
Ialpha = max(0, min(1, Ialpha));

%% Display images
figure('Name', 'Statistical Image Denoising', ... %[output:2c9c76b2]
       'Position', [100 100 1200 450]); %[output:2c9c76b2]

subplot(1,3,1); %[output:2c9c76b2]
imagesc(I, [0 1]); %[output:2c9c76b2]
axis image off; %[output:2c9c76b2]
colormap gray; %[output:2c9c76b2]
title('Original Noisy Image'); %[output:2c9c76b2]

subplot(1,3,2); %[output:2c9c76b2]
imagesc(Igeo, [0 1]); %[output:2c9c76b2]
axis image off; %[output:2c9c76b2]
title('3x3 Geometric Mean Filter'); %[output:2c9c76b2]

subplot(1,3,3); %[output:2c9c76b2]
imagesc(Ialpha, [0 1]); %[output:2c9c76b2]
axis image off; %[output:2c9c76b2]
title('3x3 Alpha-Trimmed Mean Filter, d=4'); %[output:2c9c76b2]

%% Save output images
imwrite(Igeo, 'HW4_P3_geometric_mean.png');

imwrite(Ialpha, 'HW4_P3_alpha_trimmed.png');

exportgraphics(gcf, ... %[output:group:8227a5b4] %[output:2c9c76b2]
    'HW4_P3_comparison.png'); %[output:group:8227a5b4] %[output:2c9c76b2]

%% Optional SNR evaluation
% Requires the original clean reference image.
% Select Cancel if the clean image is unavailable.

[refFile, refPath] = uigetfile( ...
    {'*.jpg;*.jpeg;*.png;*.tif', 'Image Files'}, ...
    'Select Clean Reference Image (Cancel to Skip)');

if ~isequal(refFile, 0) %[output:group:0ea9ebb6]

    Iref = imread(fullfile(refPath, refFile));

    if size(Iref,3) == 3
        Iref = 0.2989*double(Iref(:,:,1)) + ...
               0.5870*double(Iref(:,:,2)) + ...
               0.1140*double(Iref(:,:,3));
    end

    Iref = double(Iref);

    if max(Iref(:)) > 1
        Iref = Iref / 255;
    end

    if ~isequal(size(Iref), size(I))
        error('Reference and noisy image sizes must match.');
    end

    %% Calculate SNR
    signalPower = sum(Iref(:).^2);

    noiseBefore = sum((Iref(:)-I(:)).^2);
    noiseGeo = sum((Iref(:)-Igeo(:)).^2);
    noiseAlpha = sum((Iref(:)-Ialpha(:)).^2);

    SNR_before = 10*log10(signalPower/noiseBefore);
    SNR_geo = 10*log10(signalPower/noiseGeo);
    SNR_alpha = 10*log10(signalPower/noiseAlpha);

    fprintf('\nSNR Results:\n');
    fprintf('Before denoising: %.4f dB\n', SNR_before);
    fprintf('Geometric mean filter: %.4f dB\n', SNR_geo);
    fprintf('Alpha-trimmed mean filter: %.4f dB\n', SNR_alpha);

else
    disp('SNR skipped: no clean reference selected.'); %[output:54030676]
end %[output:group:0ea9ebb6]

disp('Statistical denoising completed.'); %[output:3559704f]
disp('Output images saved.'); %[output:2087fb56]


